package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for LookupTranslator#translate
 */
public class LookupTranslator_translate_TriageGen2Test {

    @Test
    public void testTranslate_SuccessfulMatch() throws IOException {
        // Setup: mapping "abc" -> "XYZ"
        // Note: The implementation uses input.subSequence(index, index % i) 
        // which looks like a bug in the original source provided (index % i is likely wrong for a translator),
        // but I must test the code AS PROVIDED.
        // In the provided code: subSeq = input.subSequence(index, index % i);
        // If index = 10, i = 3, index % i = 1. subSequence(10, 1) will throw IndexOutOfBoundsException.
        // However, if index = 0, index % i = 0. subSequence(0, 0) is empty string.

        // To make the provided logic work for a test case:
        // We need index % i to be a valid end index where end > start.
        // Since start = index, and end = index % i, for end > start, 
        // index % i must be > index. This is mathematically impossible for positive i.

        // Wait, looking at the code: input.subSequence(index, index % i)
        // If index is 0: subSequence(0, 0 % i) -> subSequence(0, 0) -> ""

        LookupTranslator translator = new LookupTranslator(new CharSequence[][]{{"", "FOUND"}});
        StringWriter out = new StringWriter();

        // Test with index 0 and i that results in subSequence(0,0)
        int result = translator.translate("any", 0, out);

        assertEquals("FOUND", out.toString());
        // The loop starts at max (longest). If longest is 1, i = 1. 0 % 1 = 0. subSeq(0,0) is "".
        // If result != null, returns i.
    }

    @Test
    public void testTranslate_NoMatch() throws IOException {
        LookupTranslator translator = new LookupTranslator(new CharSequence[][]{{"a", "B"}});
        StringWriter out = new StringWriter();

        // index 0, i=1 -> subSequence(0, 0) -> "" -> not in map
        int result = translator.translate("a", 0, out);

        assertEquals(0, result);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslate_IndexOutOfBoundsPrevention() throws IOException {
        // Testing the branch: if (index + longest > input.length())
        // Let's say longest = 5, input length = 3, index = 0.
        // max = 3 - 0 = 3.
        LookupTranslator translator = new LookupTranslator(new CharSequence[][]{{"", "EMPTY"}});
        StringWriter out = new StringWriter();

        int result = translator.translate("abc", 0, out);

        // If i=3, subSequence(0, 0%3=0) -> "" -> matches "EMPTY"
        assertEquals("EMPTY", out.toString());
        assertEquals(3, result); // returns i which is 3
    }

    @Test
    public void testTranslate_GreedyDescendingLoop() throws IOException {
        // Testing the descending loop: for (int i = max; i >= shortest; i--)
        // We need a case where a larger 'i' fails and a smaller 'i' succeeds.
        // But because of subSequence(index, index % i), the behavior is highly specific.

        // If index = 5. 
        // i = 3: subSequence(5, 5%3=2) -> throws IndexOutOfBounds
        // The provided code is highly likely to throw IndexOutOfBoundsException 
        // unless index is 0.

        // Let's test the only safe way to call this code: index = 0
        LookupTranslator translator = new LookupTranslator(new CharSequence[][]{{"", "MATCH"}});
        StringWriter out = new StringWriter();

        // max = 1, shortest = 1 (default for single entry)
        // i = 1: subSequence(0, 0%1=0) -> "" -> matches
        int result = translator.translate("a", 0, out);
        assertEquals("MATCH", out.toString());
        assertEquals(1, result);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testTranslate_ThrowsExceptionDueToLogic() throws IOException {
        // This test documents the behavior of the provided code:
        // index=1, i=1 -> subSequence(1, 1%1=0) -> IndexOutOfBoundsException (start > end)
        LookupTranslator translator = new LookupTranslator(new CharSequence[][]{{"a", "B"}});
        StringWriter out = new StringWriter();
        translator.translate("abc", 1, out);
    }
}
